foot='<footer><a class="footer-brand" href="index.html">CAO Finder</a><p>A little clarity for your next big step.</p><div><a href="blog.html">Student blog</a><a href="index.html">Explore courses ↗</a></div><small>Independent student resource. Not affiliated with the Central Applications Office. Always confirm current requirements with CAO and the college.</small></footer>'
def head(title,desc,path,schema,script=False):
 return f'''<!doctype html><html lang="en-IE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | CAO Finder</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{BASE+path}"><meta name="theme-color" content="#5954de"><meta property="og:type" content="{'website' if script else 'article'}"><meta property="og:site_name" content="CAO Finder"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{BASE+path}"><meta name="twitter:card" content="summary"><link rel="stylesheet" href="blog.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')}</script>{'<script src="blog.js" defer></script>' if script else ''}</head><body><a class="skip" href="#main">Skip to content</a>{nav}'''
def mins(a):
 return max(3,math.ceil(len(re.sub('<[^>]+>',' ',a['dek']+' '+a['take']+' '.join(h+' '+b for h,b in a['sections'])).split())/200))
def art(i):
 a=A[i]; c=CATS.index(a['cat'])
 return f'<div class="art art-{c}" aria-hidden="true"><span class="art-note">THE STUDENT EDIT</span><span class="art-symbol">{ICONS[i]}</span><span class="art-label">{LABELS[i]}</span><i></i></div>'
def card(i,compact=False):
 a=A[i]
 return f'''<article class="post-card {'compact' if compact else ''}" data-category="{e(a['cat'])}" data-search="{e((a['title']+' '+a['desc']+' '+a['cat']).lower())}"><a class="art-link" href="{a['slug']}.html" tabindex="-1" aria-hidden="true">{art(i)}</a><div class="post-info"><div class="meta"><span class="tag tag-{CATS.index(a['cat'])}">{e(a['cat'])}</span><span>{mins(a)} min read</span></div><h2><a href="{a['slug']}.html">{e(a['title'])}</a></h2><p>{e(a['desc'])}</p><a class="read-link" href="{a['slug']}.html" aria-label="Read: {e(a['title'])}">Read the guide <span aria-hidden="true">↗</span></a></div></article>'''
def cta():
 return '<section class="cta"><span class="eyebrow">YOUR NEXT STEP</span><h2>Find a course that feels like you.</h2><p>Take what you’ve learned and explore Irish college courses by points, subject, college and location.</p><a class="button" href="index.html">Explore courses <span aria-hidden="true">↗</span></a><span class="cta-doodle" aria-hidden="true">✳</span></section>'
indexschema={'@context':'https://schema.org','@type':'Blog','name':'The Student Edit — CAO Finder','url':BASE+'blog.html','description':'Practical guides for the Leaving Cert, CAO choices and college life.','blogPost':[{'@type':'BlogPosting','headline':a['title'],'url':BASE+a['slug']+'.html'} for a in A]}
out=head('Leaving Cert & CAO Student Blog','Straightforward guides to Leaving Cert study, CAO points, choosing college courses and student life. Find practical advice and your next step.','blog.html',indexschema,True)
out+='''<main id="main" class="blog-main"><section class="blog-hero"><div class="hero-copy"><span class="eyebrow"><span class="tiny-star">✳</span> THE STUDENT EDIT</span><h1>Big choices.<br>A little <span>clarity.</span></h1><p>Your guide to the Leaving Cert, CAO choices and what comes next. Practical advice, without the overwhelm.</p><div class="hero-caption"><span class="avatar-dot">✦</span> Made for your next chapter.</div></div><div class="hero-art" aria-hidden="true"><div class="paper paper-back"></div><div class="paper"><span class="paper-small">NOTE TO SELF</span><strong>You don’t need<br>it all figured<br>out. <span>Yet.</span></strong><div class="paper-line"></div><span class="paper-bottom">One step at a time. ↗</span></div><span class="hero-spark">✳</span><span class="hero-badge">YOU’VE GOT THIS</span></div></section><section class="guides" aria-labelledby="guides-title"><div class="section-top"><div><span class="eyebrow">A GOOD PLACE TO START</span><h2 id="guides-title">Guides for the way ahead</h2></div><label class="search"><span aria-hidden="true">⌕</span><input id="blog-search" type="search" placeholder="Search the guides…" aria-label="Search blog guides"></label></div><div class="filters" aria-label="Filter guides by topic">'''
for cat in ['All guides']+CATS:
 count=10 if cat=='All guides' else sum(a['cat']==cat for a in A)
 out+=f'<button type="button" data-filter="{e(cat)}" aria-pressed="{str(cat=="All guides").lower()}">{e(cat)} <span>{count}</span></button>'
out+='</div><p class="result-count" id="result-count" role="status" aria-live="polite">10 guides to help you take the next step</p><div id="posts">'+''.join(card(i) for i in range(10))+'</div><div id="empty" hidden><h3>No guides found</h3><p>Try another word or reset the filters.</p><button class="button" id="reset" type="button">Show all guides</button></div></section>'+cta()+'</main>'+foot+'</body></html>'
(ROOT/'blog.html').write_text(out)
for i,a in enumerate(A):
 path=a['slug']+'.html'
 schema={'@context':'https://schema.org','@graph':[{'@type':'BlogPosting','headline':a['title'],'description':a['desc'],'datePublished':DATE,'dateModified':DATE,'author':{'@type':'Organization','name':'CAO Finder','url':BASE},'publisher':{'@type':'Organization','name':'CAO Finder','url':BASE},'mainEntityOfPage':BASE+path,'articleSection':a['cat'],'inLanguage':'en-IE'},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'CAO Finder','item':BASE},{'@type':'ListItem','position':2,'name':'Student blog','item':BASE+'blog.html'},{'@type':'ListItem','position':3,'name':a['title'],'item':BASE+path}]}]}
 out=head(a['title'],a['desc'],path,schema)+f'<main id="main" class="article-main"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="index.html">Home</a><span>/</span><a href="blog.html">Student blog</a></nav><header class="article-header"><span class="tag tag-{CATS.index(a["cat"])}">{e(a["cat"])}</span><h1>{e(a["title"])}</h1><p class="dek">{e(a["dek"])}</p><div class="byline"><span class="author-icon">CF</span><span>By CAO Finder <span class="byline-details"><time datetime="{DATE}">19 September 2026</time> · {mins(a)} min read</span></span></div></header><div class="article-layout"><aside class="toc" aria-label="On this page"><span class="eyebrow">IN THIS GUIDE</span><ol>'
 out+=''.join(f'<li><a href="#section-{j+1}">{e(h)}</a></li>' for j,(h,b) in enumerate(a['sections']))+'</ol><a href="blog.html">← All guides</a></aside><article class="article-body"><div class="takeaway"><span class="eyebrow">THE TAKEAWAY</span><p>'+e(a['take'])+'</p></div>'
 out+=''.join(f'<section id="section-{j+1}"><h2>{e(h)}</h2>{b}</section>' for j,(h,b) in enumerate(a['sections']))
 out+=f'<section class="faq"><span class="eyebrow">ONE MORE THING</span><h2>{e(a["faq"][0])}</h2><p>{e(a["faq"][1])}</p></section><p class="editor-note">Written by CAO Finder. Official rules are linked where relevant; examples and worksheets are illustrative. Check current CAO and college information for your application year.</p></article></div><section class="related"><span class="eyebrow">KEEP EXPLORING</span><h2>A little more help</h2><div class="related-grid">'+''.join(card(n,True) for n in a['related'])+'</div></section>'+cta()+'</main>'+foot+'</body></html>'
 (ROOT/path).write_text(out)
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE+p}</loc><lastmod>{DATE}</lastmod></url>' for p in ['','blog.html']+[a['slug']+'.html' for a in A])+'</urlset>')
print('Generated blog index, 10 articles and sitemap.')
